W = lambda ms: "await new Promise(r=>setTimeout(r,%d));" % ms
CLICKB = lambda txt, ms=500: "{const b=[...document.querySelectorAll('button')].find(x=>x.textContent.trim()==='%s');b&&b.click();}%s" % (txt, W(ms))
SEARCH_KW = lambda kw: "{const i=document.querySelector('.es-search__fields input[type=text]');if(i){const s=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set;s.call(i,'%s');i.dispatchEvent(new Event('input',{bubbles:true}));}}" % kw + CLICKB('検索', 500)
POLL = lambda css: "for(let i=0;i<80&&!document.querySelector('%s');i++){await new Promise(r=>setTimeout(r,100));}" % css
