         I("2.11", "月次提供数", ".od-ro label::月次提供数", "label", "view", detail=["「合計 50個・冷蔵・常温 0〜50個」。ESスタンダードは「・冷凍 1〜20個」も。温度帯の下限・上限は子契約に固めた値（台帳 H）", "\"Tổng 50 cái, lạnh/thường 0〜50 cái\". ES Standard thêm \"đông lạnh 1〜20 cái\". Mức dưới/trên của nhóm nhiệt độ là giá trị đã cố định trong hợp đồng con (Sổ cái H)"], vi="Số lượng cung cấp hàng tháng"),
         I("2.12", "配送回数", ".od-ro label::配送回数", "label", "view", detail=["「冷蔵 2回（ES配送便）」。ESスタンダードは「・冷凍 2回」も。便は温度帯ごとに数える（台帳 H）", "\"Lạnh 2 lần (chuyến ES)\". ES Standard thêm \"đông lạnh 2 lần\". Chuyến được đếm theo nhóm nhiệt độ (Sổ cái H)"], vi="Số lần giao"),
         I("2.13", "基準数パターン（基本比×倍）", ".od-ro label::基準数パターン", "label", "view", detail=["「1倍（基準数 50個あたり × 1）」。100プラン＝2倍（注文.md §6）", "\"1 lần (mỗi 50 cái số chuẩn × 1)\". Plan 100 = 2 lần (注文.md §6)"], vi="Mẫu số chuẩn (tỷ lệ cơ bản × bội)"),
         I("2.14", "調整率", ".od-ro label::調整率", "label", "view", detail=["「0.0%（0個）」。調整率＝調整数÷食数（小数1桁の%）。表示だけで入力しない（選択肢なし）。調整数の上限はプランの食数。調整数は出荷指示・発注・理論在庫に反映される（請求はしない）。入力できるのはシステム管理だけ。発注締め日（B7・D7）のあとは入力できない（読み取り。変えたいときは代替品設定：受付簿 No.263）。調整数は「合計＝プラン数」「便の差±1」の計算に入れない（受付簿 No.269）。お試し（自動）の注文には足せない（欄は読み取り）。締めは便ごと：便が前半（A・B週）の分は B7、後半（C・D週）の分は D7 のあと（受付簿 No.270）", "\"0.0% (0 cái)\". Tỷ lệ điều chỉnh = số điều chỉnh ÷ số suất (1 chữ số thập phân, %). Chỉ hiển thị, không nhập (không có lựa chọn). Mức trên của số điều chỉnh là số suất của plan. Số điều chỉnh được phản ánh vào chỉ thị xuất hàng, đặt hàng, tồn kho lý thuyết (không tính tiền). Chỉ quản trị hệ thống mới nhập được. Sau ngày chốt đặt hàng (B7, D7) thì không nhập được (chỉ đọc; muốn đổi thì dùng thiết lập sản phẩm thay thế: Sổ tiếp nhận No.263). Số điều chỉnh không được tính vào \"tổng = số plan\" và \"chênh lệch chuyến ±1\" (Sổ tiếp nhận No.269). Không cộng được vào đơn dùng thử (tự động) (ô chỉ đọc). Chốt theo từng chuyến: chuyến nửa đầu (tuần A・B) chốt sau B7, chuyến nửa sau (tuần C・D) chốt sau D7 (Sổ tiếp nhận No.270)"],
           cond=["表示は閲覧できる役割すべて。入力はシステム管理だけで、発注締め日（B7・D7）のあとは入力できない（受付簿 No.263）", "Mọi vai trò xem được đều thấy. Chỉ quản trị hệ thống nhập được, sau ngày chốt đặt hàng (B7, D7) thì không nhập được (Sổ tiếp nhận No.263)"], vi="Tỷ lệ điều chỉnh"),
         I("2.15", "オーダー受付期間", ".od-ro label::オーダー受付期間", "label", "view", detail=["「2026-10-01〜2026-10-15」（メニューが持つ受付期間）。お試しは「発注締め日まで（B7・D7）」", "\"2026-10-01〜2026-10-15\" (thời gian nhận của menu). Dùng thử là \"đến ngày chốt đặt hàng (B7, D7)\""], vi="Thời gian nhận đơn"),
         I("2.16", "法人の登録", ".od-ro label::法人の登録", "label", "view", detail=["日時と担当者（法人・拠点のアカウント）。なければ「—」、お試し（自動）は「参照のみ」", "Ngày giờ và người phụ trách (tài khoản pháp nhân/điểm giao). Chưa có thì \"—\", dùng thử (tự động) là \"Chỉ xem\""], vi="Đăng ký của pháp nhân"),
         I("2.17", "ES の変更", ".od-ro label::ES の変更", "label", "view", detail=["日時と担当者（運営）。なければ「—」", "Ngày giờ và người phụ trách (vận hành). Chưa có thì \"—\""], vi="Thay đổi của ES"),
         I("2.18", "最終更新", ".od-ro label::最終更新", "label", "view", detail=["注文の最終更新の日時", "Ngày giờ cập nhật cuối của đơn hàng"], vi="Cập nhật lần cuối"),
         I("4", "拠点の設定（デフォルト注文・AI の提案に使う）", ".es-card::拠点の設定", "card", "view", ex=["大阪支店", "Tên điểm giao (ví dụ: chi nhánh Osaka)"],
           detail=["法人Webの月次注文「注文の設定」と同じ設定（台帳 H・注文.md §5）。デフォルト注文と AI の提案に使う", "Cùng thiết lập với \"Thiết lập đặt hàng\" của đơn hàng tháng ở Web pháp nhân (Sổ cái H, 注文.md §5). Dùng cho đơn mặc định và đề xuất của AI"], vi="Thiết lập điểm giao (dùng cho đơn mặc định và đề xuất của AI)"),
         I("4.1", "拠点の設定を直す", ".es-section-title button::拠点の設定を直す", "button", "click",
           detail=["拠点の設定を直す（モーダル。状態 010）を開く。運営が代わりに直すとき（例：お客様から電話で依頼があった）に使う", "Mở modal sửa thiết lập điểm giao (trạng thái 010). Dùng khi vận hành sửa hộ (ví dụ khách gọi điện nhờ)"],
           cond=["更新の権限がある役割だけに出す", "Chỉ hiện cho vai trò có quyền cập nhật"], vi="Sửa thiết lập điểm giao"),
         I("4.2", "カテゴリ", ".od-ro label::カテゴリ", "label", "view", detail=["「すべて（7）」。一部だけのときは「肉・魚（2／7）」。カテゴリは商品カテゴリマスタ（7つ：台帳 F）", "\"Tất cả (7)\". Nếu chỉ một phần thì \"Thịt/cá (2/7)\". Danh mục là master danh mục sản phẩm (7 loại: Sổ cái F)"], vi="Danh mục"),
         I("4.3", "短消費期限の商品", ".od-ro label::短消費期限の商品", "label", "view", detail=["取る（既定）／取らない（短消費期限なしの標準数を使う）", "Lấy (mặc định) / Không lấy (dùng số chuẩn không có hạn dùng ngắn)"], vi="Sản phẩm hạn dùng ngắn"),
         I("4.4", "商品の金額（税込）", ".od-ro label::商品の金額", "label", "view", detail=["「100円・200円」（既定は両方）。外した金額の商品は、デフォルト注文と AI の提案に入れない（手で注文はできる）", "\"100 yên, 200 yên\" (mặc định cả hai). Sản phẩm có mức giá bị bỏ chọn sẽ không đưa vào đơn mặc định và đề xuất của AI (vẫn đặt tay được)"], vi="Giá sản phẩm (đã gồm thuế)"),
         I("4.5", "次回以降も適用", ".od-ro label::次回以降も適用", "label", "view", detail=["ON（AI の提案を下書きに入れる）／OFF（運営の標準数にこの設定をかける）。既定は OFF", "ON (đưa đề xuất của AI vào bản nháp) / OFF (lấy số chuẩn của vận hành nhân với thiết lập này). Mặc định OFF"], vi="Áp dụng từ lần sau"),
         I("4.6", "対象外の商品（毎月0個）", ".od-ro label::対象外の商品", "label", "view", detail=["商品名を「・」でつなぐ。なければ「なし」", "Nối tên sản phẩm bằng \"・\". Không có thì \"Không\""], vi="Sản phẩm loại trừ (mỗi tháng 0 cái)"),
         I("4.7", "最終更新", ".es-card:has(.mo-note) .od-ro:last-child label", "label", "view", detail=["設定を最後に直した日時と担当者。直していなければ「—（初期値のまま）」", "Ngày giờ và người phụ trách của lần sửa thiết lập cuối. Chưa sửa thì \"— (giữ giá trị ban đầu)\""], vi="Cập nhật lần cuối"),
         I("4.8", "拠点の設定の注記", ".es-card:has(.mo-note) .mo-note", "label", "view",
           detail=["「法人Webの「商品注文 ＞ 注文の設定」と同じ設定です。運営が直したときは、翌月のメニューから使います（この月の注文は変えません。直すときは上の「編集」）。」", "\"Cùng thiết lập với 「Đặt hàng sản phẩm > Thiết lập đặt hàng」 của Web pháp nhân. Khi vận hành sửa, sẽ dùng từ menu tháng sau (không đổi đơn của tháng này. Muốn sửa thì bấm \"Chỉnh sửa\" ở trên).\""], vi="Ghi chú của thiết lập điểm giao"),
         I("5", "注文内容", ".es-card::注文内容", "card", "view", ex=["照り焼きチキン", "Tên sản phẩm (ví dụ: gà teriyaki)"], vi="Nội dung đơn hàng"),
         I("5.1", "統計", ".es-section-title button::統計", "button", "click", detail=["統計（モーダル。状態 009）を開く", "Mở modal thống kê (trạng thái 009)"], vi="Thống kê"),
         I("5.2", "商品の検索", ".es-search", "area", "view", pattern="P-LIST",
           detail=["この注文の商品の表を絞る。条件は「検索」か Enter で反映（ページ送りはなく、表は全件）。「注文している商品のみ表示」は既定で ON", "Thu hẹp bảng sản phẩm của đơn này. Áp dụng điều kiện bằng \"Tìm kiếm\" hoặc Enter (không phân trang, bảng hiện toàn bộ). \"Chỉ hiện sản phẩm đã đặt\" mặc định ON"], vi="Tìm kiếm sản phẩm"),
         I("5.2.1", "キーワード（商品）", ".es-search__fields input[placeholder^=商品名]", "text", "input", req="－", len="文字列 60", ex=["チキン", "Từ khóa tên sản phẩm/ID (ví dụ: gà)"], detail=["商品名・商品IDを部分一致で探す", "Tìm khớp một phần theo tên sản phẩm và ID sản phẩm"], vi="Từ khóa (sản phẩm)"),
         I("5.2.2", "カテゴリ", ".es-search__fields select[aria-label=カテゴリ]", "select", "select", req="－", len="選択", init=["（指定なし）", "(Không chỉ định)"], ex=["肉", "Tên danh mục (ví dụ: thịt)"], detail=["商品カテゴリマスタの7つ", "7 loại của master danh mục sản phẩm"], vi="Danh mục"),
         I("5.2.3", "保存方法", ".es-search__fields select[aria-label=保存方法]", "select", "select", req="－", len="選択", init=["（指定なし）", "(Không chỉ định)"], ex=["冷凍", "Cách bảo quản (ví dụ: đông lạnh)"], detail=["冷蔵／常温／冷凍", "Lạnh / Thường / Đông lạnh"], vi="Cách bảo quản"),
         I("5.2.4", "商品タグ", ".es-search__fields select[aria-label=商品タグ]", "select", "select", req="－", len="選択", init=["（指定なし）", "(Không chỉ định)"], ex=["NEW", "Thẻ sản phẩm (ví dụ: NEW)"],
           detail=["NEW／再登場／定番／冷たくても美味しい", "NEW / Tái xuất hiện / Món cố định / Lạnh vẫn ngon"], vi="Thẻ sản phẩm"),
         I("5.2.5", "短消費期限なし", ".mo-chk::短消費期限なし", "check", "check", req="－", len="選択", init=["OFF", "OFF"], ex=["ON", "Giá trị bật/tắt (ví dụ: ON)"], detail=["ON で短消費期限の区分がある商品を出さない", "ON thì không hiện sản phẩm có phân loại hạn dùng ngắn"], vi="Không hạn dùng ngắn"),
         I("5.2.6", "注文している商品のみ表示", ".mo-chk::注文している商品のみ表示", "check", "check", req="－", len="選択", init=["ON", "ON"], ex=["OFF", "Giá trị bật/tắt (ví dụ: OFF)"], detail=["ON で 1個以上入っている商品だけ（注文・調整とも0の商品は隠す）。OFF でこの拠点で注文できる全商品", "ON: chỉ sản phẩm có từ 1 cái trở lên (ẩn sản phẩm có đặt và điều chỉnh đều 0). OFF: toàn bộ sản phẩm điểm giao này đặt được"], vi="Chỉ hiện sản phẩm đã đặt"),
         I("5.2.7", "クリア／検索", ".es-search__main", "button", "click", detail=["クリア＝条件をすべて外す（「注文している商品のみ表示」も OFF になる）。検索＝条件を反映", "Xóa = bỏ mọi điều kiện (\"Chỉ hiện sản phẩm đã đặt\" cũng thành OFF). Tìm kiếm = áp dụng điều kiện"], vi="Xóa / Tìm kiếm"),
         I("5.3", "合計の表示", ".od-sum", "area", "view", detail=["注文の合計と便ごとの数。条件に合わない行は赤", "Tổng đơn và số lượng theo từng chuyến. Dòng không đạt điều kiện hiện màu đỏ"], vi="Hiển thị tổng"),
         I("5.3.1", "合計／プラン数", ".od-sum__row.is-main", "label", "view", detail=["「合計 50 / 50個」。プラン数と違うと赤（台帳 E：合計＝プラン数が必須）", "\"Tổng 50 / 50 cái\". Khác số plan thì đỏ (Sổ cái E: bắt buộc tổng = số plan)"], vi="Tổng / Số plan"),
         I("5.3.2", "冷蔵・常温", ".od-sum__row::冷蔵・常温", "label", "view", detail=["「冷蔵・常温 50（0〜50個）」。範囲の外は赤", "\"Lạnh/thường 50 (0〜50 cái)\". Ngoài phạm vi thì đỏ"], vi="Lạnh/thường"),
         I("5.3.4", "調整数", ".od-sum__row::調整数", "label", "view", detail=["「調整数 0 / 0個」（運営がサービスで足した数・請求しない）。上限（プランの食数）を超えると赤。調整数は出荷指示・発注・理論在庫に反映される（請求はしない）。入力できるのはシステム管理だけ。発注締め日（B7・D7）のあとは入力できない（読み取り。変えたいときは代替品設定：受付簿 No.263）。調整数は「合計＝プラン数」「便の差±1」の計算に入れない（受付簿 No.269）。お試し（自動）の注文には足せない（欄は読み取り）。締めは便ごと：便が前半（A・B週）の分は B7、後半（C・D週）の分は D7 のあと（受付簿 No.270）", "\"Số điều chỉnh 0 / 0 cái\". Vượt mức trên (số suất của plan) thì đỏ. Số điều chỉnh được phản ánh vào chỉ thị xuất hàng, đặt hàng, tồn kho lý thuyết (không tính tiền). Chỉ quản trị hệ thống mới nhập được. Sau ngày chốt đặt hàng (B7, D7) thì không nhập được (chỉ đọc; muốn đổi thì dùng thiết lập sản phẩm thay thế: Sổ tiếp nhận No.263). Số điều chỉnh không được tính vào \"tổng = số plan\" và \"chênh lệch chuyến ±1\" (Sổ tiếp nhận No.269). Không cộng được vào đơn dùng thử (tự động) (ô chỉ đọc). Chốt theo từng chuyến: chuyến nửa đầu (tuần A・B) chốt sau B7, chuyến nửa sau (tuần C・D) chốt sau D7 (Sổ tiếp nhận No.270)"],
           cond=["表示は閲覧できる役割すべて。入力はシステム管理だけで、発注締め日（B7・D7）のあとは入力できない（受付簿 No.263）", "Mọi vai trò xem được đều thấy. Chỉ quản trị hệ thống nhập được, sau ngày chốt đặt hàng (B7, D7) thì không nhập được (Sổ tiếp nhận No.263)"], vi="Số điều chỉnh"),
         I("5.3.5", "便ごとの数", ".od-sum__dl", "label", "view", detail=["便ごとに「第1便 11/10 注文数 25 / 25個」。目標（温度帯の合計を便の数で割った数）との差が1個を超えると赤（便の差 ±1 以内：台帳 E）", "Theo từng chuyến \"Chuyến 1 11/10 số đặt 25 / 25 cái\". Chênh lệch với mục tiêu (tổng nhóm nhiệt độ chia số chuyến) quá 1 cái thì đỏ (chênh lệch chuyến trong ±1: Sổ cái E)"], vi="Số lượng theo chuyến"),
         I("5.4", "注文内容の表", ".mo-ordtbl", "table", "view",
           detail=["1行＝1商品。左から No・写真・商品名・カテゴリ・短消費期限・販売価格（税込）・便ごとの 注文数／調整数・合計数。その便に入れられない商品（冷凍の商品の冷蔵の便など）は「—」。公開後にメニューから外した商品が注文に残っているときは、その行に「メニューから外れました」（No.5.4.10）", "1 dòng = 1 sản phẩm. Từ trái: No, ảnh, tên sản phẩm, danh mục, hạn dùng ngắn, giá bán (đã gồm thuế), số đặt/số điều chỉnh theo chuyến, tổng. Sản phẩm không đưa vào chuyến đó được (sản phẩm đông lạnh ở chuyến lạnh...) hiện \"—\". Sản phẩm đã bỏ khỏi menu sau khi công khai mà vẫn còn trong đơn thì dòng đó hiện \"メニューから外れました\" (No.5.4.10)"], vi="Bảng nội dung đơn hàng"),
         I("5.4.1", "写真", ".mo-ordtbl img", "label", "view", detail=["商品マスタのメイン画像（サムネイル）", "Ảnh chính của master sản phẩm (ảnh thu nhỏ)"], vi="Ảnh"),
         I("5.4.2", "商品名", ".mo-ordtbl td.w", "label", "view", detail=["商品名（太字）と、その下に「商品ID・温度帯（冷蔵・冷凍など）」。日本語の商品名だけを出す（商品名（英語）は法人Web・個人アプリの表示用で、運営の注文の画面には出さない：受付簿 No.235）", "Tên sản phẩm (in đậm) và bên dưới \"ID sản phẩm, nhóm nhiệt độ (lạnh, đông lạnh...)\". Chỉ hiện tên tiếng Nhật (tên sản phẩm (tiếng Anh) dùng để hiển thị ở Web pháp nhân/app cá nhân, không hiện ở màn hình đơn hàng của vận hành: Sổ tiếp nhận No.235)"], vi="Tên sản phẩm"),
