         I("9.6", "キャンセル", ".es-dialog__foot button::キャンセル", "button", "click", detail=["変更していれば Q02。変更なしならそのまま閉じる", "Nếu đã thay đổi thì Q02. Chưa thay đổi thì đóng luôn"], err=["Q02"], vi="Hủy bỏ"),
