         I("5.11", "行のチェック", ".mo-ordtbl td .es-check", "check", "check", req="－", len="選択", init=["OFF", "OFF"], ex=["ON", "Giá trị bật/tắt (ví dụ: ON)"], detail=["商品の行ごとに選ぶ。選ぶと行に色が付く", "Chọn theo từng dòng sản phẩm. Khi chọn dòng được tô màu"], vi="Ô chọn của dòng"),
